<?php
declare(strict_types=1);
function navlink(string $path,string $label,string $icon,string $active): void {
    echo '<a class="nav-link'.($active===$path?' active':'').'" href="'.e(current_path($path)).'"><span class="nav-icon" aria-hidden="true">'.$icon.'</span>'.e($label).'</a>';
}
