    $u=user();$s=setting();
    ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#173e42"><title><?=e($title)?> · <?=e($s['business_name']??'Farmacia La Bendición')?></title><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head><body><a href="#principal" class="skip-link">Ir al contenido</a>
    <div class="app-shell"><aside class="sidebar" id="sidebar" aria-label="Navegación principal"><a class="brand" href="index.php"><span class="brand-mark" aria-hidden="true">+</span><span><strong>La Bendición</strong><small>Gestión de farmacia</small></span></a><div class="sidebar-group"><span class="sidebar-label">OPERACIONES</span>
    <?php navlink('dashboard','Inicio','▦',$active);navlink('sale-new','Nueva venta','◈',$active);navlink('products','Productos','▤',$active);navlink('inventory','Inventario','▥',$active);navlink('sales','Historial de ventas','◷',$active);
    if(owner()){navlink('purchases','Compras','⇥',$active);navlink('providers','Proveedores','◉',$active);navlink('alerts','Alertas','⚑',$active);navlink('reports','Reporte diario','▧',$active);}
    if(can_clients())navlink('clients','Clientes','♙',$active);
    if(owner()){echo '</div><div class="sidebar-group"><span class="sidebar-label">ADMINISTRACIÓN</span>';navlink('users','Usuarios','♧',$active);navlink('settings','Configuración','⚙',$active);navlink('audit','Auditoría','◫',$active);}
    ?></div><div class="sidebar-bottom"><div class="avatar"><?=e(strtoupper(substr($u['name'],0,1)))?></div><div class="user-info"><strong><?=e($u['name'])?></strong><small><?=owner()?'Propietaria':'Apoyo autorizado'?></small></div><form method="post" action="index.php?route=logout"><?=csrf_field()?><button class="logout" aria-label="Cerrar sesión" title="Cerrar sesión">↪</button></form></div></aside>
    <div class="main-area"><header class="topbar"><button id="menu-toggle" class="menu-toggle" type="button" aria-label="Abrir navegación" aria-expanded="false" aria-controls="sidebar">☰</button><span class="topbar-title">Farmacia La Bendición</span><span class="topbar-date"><?=e(date('d/m/Y'))?></span></header><main id="principal" class="content" tabindex="-1"><div class="page-heading"><div><h1><?=e($title)?></h1><p><?=e($description)?></p></div></div>
    <?php if(isset($_SESSION['flash'])){$f=$_SESSION['flash'];unset($_SESSION['flash']);?><div class="alert <?=e($f['type'])?>" role="alert"><?=e($f['message'])?></div><?php }
}
function footer_view(): void { ?>
    </main><footer class="footer">Sistema interno · Los comprobantes no sustituyen facturas fiscales autorizadas.</footer></div></div></body></html>
    <?php }
function small_action(string $route,int $id,string $label,string $class=''): void { echo '<form class="inline" method="post" action="index.php?route='.e($route).'">'.csrf_field().'<input type="hidden" name="id" value="'.$id.'"><button type="submit" class="btn sm '.$class.'" data-confirm="¿Confirma este cambio de estado?">'.e($label).'</button></form>'; }
function status_badge(bool $ok,string $true='Activo',string $false='Inactivo'): string { return '<span class="pill '.($ok?'ok':'muted').'">'.e($ok?$true:$false).'</span>'; }
function empty_state(string $message): void { echo '<div class="empty-state"><span aria-hidden="true">◎</span><p>'.e($message).'</p></div>'; }
function title_actions(string $text,string $route): void {echo '<div class="actions"><a class="btn primary" href="'.e(current_path($route)).'">+ '.e($text).'</a></div>';}
function valid_query_id(): int {return positive_int($_GET['id']??null,'Identificador');}
function display_page(string $route): void {
    if($route==='login') {login_view();return;}
    switch($route){
        case 'dashboard': dashboard_view();break;
        case 'products':products_view();break;
        case 'product-form':product_form_view();break;
        case 'inventory':inventory_view();break;
        case 'adjust-form':adjust_view();break;
        case 'alerts':alerts_view();break;
        case 'sale-new':sale_form_view();break;
        case 'sales':sales_view();break;
        case 'receipt':receipt_view();break;
        case 'purchases':purchases_view();break;
        case 'purchase-new':purchase_form_view();break;
        case 'purchase-detail':purchase_detail_view();break;
        case 'providers':providers_view();break;
        case 'provider-form':provider_form_view();break;
        case 'clients':clients_view();break;
        case 'client-form':client_form_view();break;
        case 'users':users_view();break;
        case 'user-form':user_form_view();break;
        case 'reports':reports_view();break;
        case 'settings':settings_view();break;
        case 'audit':audit_view();break;
        default:render_error('Esta sección no existe.',404);
    }
}
function login_view(): void {
    if(user())redirect('dashboard');
    ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Iniciar sesión | Farmacia La Bendición</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-body"><main class="auth-wrap"><form method="post" action="index.php?route=login" class="auth-card"><div class="auth-logo">+</div><span class="eyebrow">SISTEMA DE GESTIÓN</span><h1>Bienvenido a La Bendición</h1><p>Acceda con las credenciales asignadas por la propietaria.</p><?php if(isset($_SESSION['flash'])){$f=$_SESSION['flash'];unset($_SESSION['flash']);?><div class="alert <?=e($f['type'])?>" role="alert"><?=e($f['message'])?></div><?php } ?><?=csrf_field()?><label>Nombre de usuario<input type="text" name="username" required autocomplete="username" maxlength="50" autofocus></label><label>Contraseña<input type="password" name="password" required autocomplete="current-password"></label><button class="btn primary full" type="submit">Ingresar al sistema</button><p class="hint center">Acceso reservado al personal autorizado.</p></form></main></body></html><?php
}
function dashboard_view(): void {
    $today=date('Y-m-d');
    $total=owner()?fetch('SELECT COUNT(*) n,COALESCE(SUM(total),0) amount FROM sales WHERE created_at>=? AND created_at<?',[$today,date('Y-m-d',strtotime('+1 day'))]):fetch('SELECT COUNT(*) n,COALESCE(SUM(total),0) amount FROM sales WHERE created_at>=? AND created_at<? AND user_id=?',[$today,date('Y-m-d',strtotime('+1 day')),user()['id']]);
    $prods=fetch('SELECT COUNT(*) n FROM products WHERE active=1');
    $stock=fetch('SELECT COALESCE(SUM(available_qty),0) n FROM lots');
    $low=fetch('SELECT COUNT(*) n FROM products p WHERE p.active=1 AND p.min_stock IS NOT NULL AND '.stock_expr().'<=p.min_stock');
    $latest=owner()?rows('SELECT s.id,s.receipt_no,s.created_at,s.total,u.name FROM sales s JOIN users u ON u.id=s.user_id ORDER BY s.id DESC LIMIT 6'):rows('SELECT s.id,s.receipt_no,s.created_at,s.total,u.name FROM sales s JOIN users u ON u.id=s.user_id WHERE s.user_id=? ORDER BY s.id DESC LIMIT 6',[user()['id']]);
    header_view('Panel principal','Un resumen de la actividad y accesos a las tareas habituales.','dashboard');
    ?><div class="stats-grid"><div class="stat-card"><span class="stat-label"><?=owner()?'Ventas del día':'Sus ventas de hoy'?></span><strong><?=e($total['n'])?></strong><small>Operaciones confirmadas</small></div><div class="stat-card"><span class="stat-label"><?=owner()?'Total vendido hoy':'Su total vendido hoy'?></span><strong><?=money($total['amount'])?></strong><small>Pagos en efectivo</small></div><div class="stat-card"><span class="stat-label">Productos activos</span><strong><?=e($prods['n'])?></strong><small>En el catálogo</small></div><div class="stat-card"><span class="stat-label">Existencias registradas</span><strong><?=e($stock['n'])?></strong><small>Unidades, incluidos lotes vencidos</small></div></div>
    <div class="columns"><section class="panel"><div class="panel-head"><div><h2>Acciones rápidas</h2><p>Seleccione qué necesita hacer.</p></div></div><div class="quick-grid"><a href="index.php?route=sale-new" class="quick-link"><span class="quick-icon">◈</span><strong>Registrar venta</strong><small>Nuevo cobro en efectivo</small></a><a href="index.php?route=products" class="quick-link"><span class="quick-icon">▤</span><strong>Consultar producto</strong><small>Precio y disponibilidad</small></a><?php if(owner()):?><a href="index.php?route=purchase-new" class="quick-link"><span class="quick-icon">⇥</span><strong>Registrar compra</strong><small>Facturas y recepción</small></a><a href="index.php?route=alerts" class="quick-link"><span class="quick-icon">⚑</span><strong>Revisar alertas</strong><small><?=e($low['n'])?> productos con stock bajo</small></a><?php endif;?></div></section><section class="panel"><div class="panel-head"><div><h2>Ventas recientes</h2><p><?=owner()?'Últimas operaciones del establecimiento.':'Sus operaciones recientes.'?></p></div><a class="text-link" href="index.php?route=sales">Ver historial</a></div><?php if(!$latest): empty_state('Todavía no se han registrado ventas.'); else:?><div class="simple-list"><?php foreach($latest as $s):?><a class="simple-row" href="index.php?route=receipt&id=<?=$s['id']?>"><div><strong><?=e($s['receipt_no'])?></strong><small><?=e(date('d/m H:i',strtotime($s['created_at'])))?> · <?=e($s['name'])?></small></div><b><?=money($s['total'])?></b></a><?php endforeach;?></div><?php endif;?></section></div>
    <?php if(owner()): $config=setting();if($config['expiry_alert_days']===null):?><div class="notice"><strong>Alertas de vencimiento sin configurar.</strong> Defina el período en <a href="index.php?route=settings">Configuración</a> antes de confiar en este control.</div><?php endif; endif;
    footer_view();
}
function products_view(): void {
    $products=products_with_stock(); header_view('Productos','Busque medicamentos, revise precios, condición de venta y existencias.','products');
    if(owner())title_actions('Nuevo producto','product-form');
    ?><section class="panel"><div class="table-toolbar"><label class="search-label">Buscar producto<input class="search" type="search" placeholder="Código, nombre o categoría..." data-table-search="products-table"></label><span class="hint"><?=count($products)?> registros</span></div><div class="table-scroll"><table id="products-table"><thead><tr><th>Código y producto</th><th>Clasificación</th><th>Precio</th><th>Existencia</th><th>Vendible</th><th>Estado</th><?php if(owner()):?><th>Acciones</th><?php endif;?></tr></thead><tbody><?php foreach($products as $p):?><tr><td><strong><?=e($p['name'])?></strong><small><?=e($p['code'])?><?= $p['category']?' · '.e($p['category']):''?></small></td><td><?= $p['requires_prescription']?'<span class="pill warn">Requiere prescripción</span>':'<span class="pill neutral">Venta abierta</span>'?></td><td><?=money($p['sale_price'])?></td><td><?=e($p['stock'])?><?php if($p['min_stock']!==null && (int)$p['stock']<=(int)$p['min_stock']):?> <span class="pill danger">Bajo</span><?php endif;?></td><td><?=e($p['sellable_stock'])?></td><td><?=status_badge((bool)$p['active'])?></td><?php if(owner()):?><td class="nowrap"><a class="btn sm" href="index.php?route=product-form&id=<?=$p['id']?>">Editar</a> <?php small_action('toggle-product',(int)$p['id'],(int)$p['active']===1?'Desactivar':'Activar');?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php if(!$products)empty_state('Aún no existen productos registrados.');?></section><p class="hint below">Existencia total incluye unidades vencidas. «Vendible» excluye los lotes vencidos; la venta volverá a validar el inventario al confirmarse.</p><?php footer_view();
}
function product_form_view(): void {
    require_owner();$id=($_GET['id']??'')!==''?valid_query_id():null;
    $p=$id?fetch('SELECT * FROM products WHERE id=?',[$id]):null;if($id&&!$p)render_error('Producto inexistente.',404);
    header_view($id?'Editar producto':'Nuevo producto','Información de identificación, precio y umbral de reposición.','products');
    ?><section class="panel form-panel"><form method="post" action="index.php?route=save-product"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($id)?>"><div class="form-grid"><label>Código del producto <span class="required">*</span><input name="code" value="<?=e($p['code']??'')?>" maxlength="60" required></label><label>Nombre del producto <span class="required">*</span><input name="name" value="<?=e($p['name']??'')?>" maxlength="180" required></label><label>Categoría<input name="category" value="<?=e($p['category']??'')?>" maxlength="100" placeholder="Ej. analgésico"></label><label>Precio de venta (C$) <span class="required">*</span><input name="sale_price" type="number" step="0.01" min="0" max="9999999999.99" value="<?=e($p['sale_price']??'')?>" required></label><label>Condición de venta <span class="required">*</span><select name="requires_prescription"><option value="0" <?=empty($p['requires_prescription'])?'selected':''?>>Venta abierta</option><option value="1" <?=!empty($p['requires_prescription'])?'selected':''?>>Requiere prescripción</option></select></label><label>Umbral de stock bajo<input name="min_stock" type="number" min="0" step="1" value="<?=e($p['min_stock']??'')?>" placeholder="Sin configurar"><small>La alerta se activa con existencias ≤ al valor indicado.</small></label><label class="wide">Descripción (opcional)<textarea name="description" maxlength="500" rows="3"><?=e($p['description']??'')?></textarea></label></div><div class="form-actions"><a class="btn" href="index.php?route=products">Cancelar</a><button type="submit" class="btn primary">Guardar producto</button></div></form></section><?php footer_view();
}
function inventory_view():void{
    $data=products_with_stock();
    $lots=rows('SELECT l.*,p.name,p.code FROM lots l JOIN products p ON p.id=l.product_id WHERE l.available_qty>0 ORDER BY p.name,l.expiry_date IS NULL,l.expiry_date,l.id');
    $mov=owner()?rows('SELECT m.*,p.name,u.name responsible FROM movements m JOIN products p ON p.id=m.product_id JOIN users u ON u.id=m.user_id ORDER BY m.id DESC LIMIT 30'):[];
    header_view('Inventario','Existencias por producto y lote; registro de las entradas y salidas.','inventory');
    if(owner())title_actions('Registrar ajuste justificado','adjust-form');
    ?><div class="columns"><section class="panel"><div class="panel-head"><h2>Saldo por producto</h2></div><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Existencia total</th><th>Disponible para venta</th></tr></thead><tbody><?php foreach($data as $p):?><tr><td><?=e($p['name'])?><small><?=e($p['code'])?></small></td><td><?=e($p['stock'])?></td><td><?=e($p['sellable_stock'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$data)empty_state('No hay productos.');?></section><section class="panel"><div class="panel-head"><h2>Lotes con existencias</h2></div><div class="table-scroll"><table><thead><tr><th>Producto / lote</th><th>Vence</th><th>Cantidad</th></tr></thead><tbody><?php foreach($lots as $l):?><tr><td><?=e($l['name'])?><small><?=e($l['lot_code']?:'Lote sin código')?> · #<?=e($l['id'])?></small></td><td><?=e($l['expiry_date']?:'No registrada')?><?php if($l['expiry_date']&&$l['expiry_date']<date('Y-m-d')):?> <span class="pill danger">Vencido</span><?php endif;?></td><td><?=e($l['available_qty'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$lots)empty_state('Aún no hay lotes con existencias.');?></section></div><?php if(owner()):?><section class="panel"><div class="panel-head"><h2>Últimos movimientos</h2><p>Se conserva el usuario y la fecha de cada operación.</p></div><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Responsable</th></tr></thead><tbody><?php foreach($mov as $m):?><tr><td><?=e($m['created_at'])?></td><td><?=e($m['name'])?></td><td><?=e(str_replace('_',' ',$m['type']))?></td><td class="<?= (int)$m['quantity']<0?'negative':'positive'?>"><?= (int)$m['quantity']>0?'+':'' ?><?=e($m['quantity'])?></td><td><?=e($m['responsible'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$mov)empty_state('No hay movimientos todavía.');?></section><?php endif;footer_view();
}
function adjust_view():void{
    require_owner();$products=rows('SELECT id,name,code FROM products ORDER BY name');
    $lots=rows('SELECT l.id,l.product_id,l.lot_code,l.expiry_date,l.available_qty,p.name FROM lots l JOIN products p ON p.id=l.product_id WHERE l.available_qty>0 ORDER BY p.name,l.id');
    header_view('Ajuste de inventario','Para registrar saldos iniciales o corregir una diferencia documentada.','inventory');
    ?><div class="notice"><strong>Control de integridad:</strong> indique siempre el motivo. Las entradas crean un lote; las salidas se descuentan de un lote concreto. Ninguna modificación borra el historial.</div><section class="panel form-panel"><form method="post" action="index.php?route=adjust-stock"><?=csrf_field()?><div class="form-grid"><label>Producto <span class="required">*</span><select name="product_id" required><option value="">Seleccione...</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'].' ('.$p['code'].')')?></option><?php endforeach;?></select></label><label>Tipo de ajuste <span class="required">*</span><select name="movement_type" id="movement-type"><option value="entrada">Entrada / saldo inicial</option><option value="salida">Salida / corrección</option></select></label><label>Cantidad <span class="required">*</span><input name="quantity" type="number" min="1" step="1" required></label><label class="exit-only" hidden>Lote del que se descuenta <span class="required">*</span><select name="lot_id" id="adjust-lot"><option value="">Seleccione un lote</option><?php foreach($lots as $l):?><option data-product-id="<?=$l['product_id']?>" value="<?=$l['id']?>"><?=e($l['name'].' · #'.$l['id'].' · '.$l['lot_code'].' · '.$l['available_qty'].' unid.')?></option><?php endforeach;?></select></label><label class="entry-only">Código de lote<input name="lot_code" maxlength="90" placeholder="Si consta en el empaque"></label><label class="entry-only">Fecha de vencimiento<input name="expiry_date" type="date"></label><label class="wide">Motivo del ajuste <span class="required">*</span><textarea name="reason" required minlength="6" maxlength="255" rows="3" placeholder="Ej. inventario inicial contado físicamente el ..."></textarea></label></div><div class="form-actions"><a href="index.php?route=inventory" class="btn">Cancelar</a><button type="submit" class="btn primary" data-confirm="¿Confirma el ajuste? Se registrará en la auditoría.">Guardar ajuste</button></div></form></section><?php footer_view();
}
function alerts_view():void{
    require_owner();$s=setting();$all=rows('SELECT p.id,p.code,p.name,p.min_stock,'.stock_expr().' AS stock FROM products p WHERE p.active=1 AND p.min_stock IS NOT NULL AND '.stock_expr().'<=p.min_stock ORDER BY p.name');
    $expired=rows('SELECT l.*,p.name,p.code FROM lots l JOIN products p ON p.id=l.product_id WHERE p.active=1 AND l.available_qty>0 AND l.expiry_date<CURDATE() ORDER BY l.expiry_date');
    $upcoming=$s['expiry_alert_days']===null?[]:rows('SELECT l.*,p.name,p.code FROM lots l JOIN products p ON p.id=l.product_id WHERE p.active=1 AND l.available_qty>0 AND l.expiry_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL '.(int)$s['expiry_alert_days'].' DAY) ORDER BY l.expiry_date');
    header_view('Alertas de inventario','Productos que requieren reposición o revisión de vencimiento.','alerts');
    if($s['expiry_alert_days']===null):?><div class="alert warning" role="status">El período de vencimiento aún no fue configurado. <a href="index.php?route=settings">Definir días de alerta</a>.</div><?php endif;?>
    <div class="stats-grid three"><div class="stat-card"><span class="stat-label">Stock bajo</span><strong><?=count($all)?></strong></div><div class="stat-card"><span class="stat-label">Lotes vencidos</span><strong><?=count($expired)?></strong></div><div class="stat-card"><span class="stat-label">Próximos a vencer</span><strong><?=$s['expiry_alert_days']===null?'—':count($upcoming)?></strong><small><?=$s['expiry_alert_days']===null?'Período pendiente':'En los próximos '.e($s['expiry_alert_days']).' días'?></small></div></div>
    <section class="panel"><div class="panel-head"><h2>Existencias bajas</h2></div><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Existencia</th><th>Umbral definido</th></tr></thead><tbody><?php foreach($all as $p):?><tr><td><?=e($p['name'])?><small><?=e($p['code'])?></small></td><td><span class="pill danger"><?=e($p['stock'])?></span></td><td><?=e($p['min_stock'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$all)empty_state('Ningún producto ha alcanzado su umbral de alerta.');?></section>
    <section class="panel"><div class="panel-head"><h2>Lotes vencidos</h2></div><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Lote</th><th>Vencimiento</th><th>Existencia</th></tr></thead><tbody><?php foreach($expired as $l):?><tr><td><?=e($l['name'])?></td><td><?=e($l['lot_code']?:'#'.$l['id'])?></td><td class="negative"><?=e($l['expiry_date'])?></td><td><?=e($l['available_qty'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$expired)empty_state('No se registran lotes vencidos con existencias.');?></section>
    <section class="panel"><div class="panel-head"><h2>Próximos a vencer</h2></div><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Lote</th><th>Fecha límite</th><th>Existencia</th></tr></thead><tbody><?php foreach($upcoming as $l):?><tr><td><?=e($l['name'])?></td><td><?=e($l['lot_code']?:'#'.$l['id'])?></td><td><?=e($l['expiry_date'])?></td><td><?=e($l['available_qty'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$upcoming)empty_state($s['expiry_alert_days']===null?'Configure el período para consultar esta alerta.':'No hay lotes próximos a vencer en el período definido.');?></section><?php footer_view();
}
function sale_form_view():void{
    $list=products_with_stock(true);
    $sellable=array_values(array_filter($list,fn($p)=>(int)$p['sellable_stock']>0));
    $clients=can_clients()?rows('SELECT id,name FROM clients WHERE active=1 ORDER BY name'):[];
    header_view('Nueva venta','Seleccione los productos; el sistema calculará el total antes de confirmar.','sale-new');
    ?><div class="notice"><strong>Venta en efectivo.</strong> No se aplican descuentos ni se procesan devoluciones. El inventario se descuenta únicamente después de confirmar. Los medicamentos con prescripción se identifican para aplicar el procedimiento autorizado por la farmacia.</div>
    <section class="panel"><form method="post" action="index.php?route=sale-create" id="sale-form" data-kind="sale"><?=csrf_field()?><input type="hidden" name="request_token" value="<?=bin2hex(random_bytes(16))?>">
    <div class="panel-head"><div><h2>Detalle de la venta</h2><p>Puede añadir varios productos al mismo comprobante.</p></div></div>
