    ?><section class="panel"><div class="table-toolbar"><label class="search-label">Buscar comprobante<input type="search" class="search" data-table-search="sales-table" placeholder="Número, fecha o responsable"></label></div><div class="table-scroll"><table id="sales-table"><thead><tr><th>Comprobante</th><th>Fecha y hora</th><th>Responsable</th><th>Forma de pago</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($saleList as $sale):?><tr><td><strong><?=e($sale['receipt_no'])?></strong></td><td><?=e($sale['created_at'])?></td><td><?=e($sale['responsible'])?></td><td>Efectivo</td><td><strong><?=money($sale['total'])?></strong></td><td><a class="btn sm" href="index.php?route=receipt&id=<?=$sale['id']?>">Comprobante</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$saleList)empty_state('No existen ventas para mostrar.');?></section><?php footer_view();
}
function receipt_view():void{
    $id=valid_query_id();$sale=fetch('SELECT s.*,u.name responsible,c.name client FROM sales s JOIN users u ON u.id=s.user_id LEFT JOIN clients c ON c.id=s.client_id WHERE s.id=?',[$id]);
    if(!$sale)render_error('La venta indicada no existe.',404);
    if(!owner()&&(int)$sale['user_id']!==(int)user()['id'])render_error('No puede consultar ventas registradas por otra persona.',403);
    $lines=rows('SELECT product_name,quantity,unit_price,line_total FROM sale_lines WHERE sale_id=? ORDER BY id',[$id]);
    $settings=setting();header_view('Comprobante de venta','Constancia interna de la operación realizada.','sales');
    ?><div class="receipt-actions"><a class="btn" href="index.php?route=sales">← Volver a ventas</a><button class="btn primary" type="button" id="print-receipt">Imprimir comprobante</button></div>
    <article id="receipt-paper" class="receipt-paper"><header class="receipt-head"><div class="receipt-symbol">+</div><h2><?=e($settings['business_name'])?></h2><?php if($settings['business_address']):?><p><?=e($settings['business_address'])?></p><?php endif;?><?php if($settings['business_phone']):?><p>Tel.: <?=e($settings['business_phone'])?></p><?php endif;?><strong>COMPROBANTE BÁSICO DE VENTA</strong><p class="receipt-number"><?=e($sale['receipt_no'])?></p></header><div class="receipt-meta"><div><span>Fecha y hora</span><strong><?=e($sale['created_at'])?></strong></div><div><span>Atendió</span><strong><?=e($sale['responsible'])?></strong></div><?php if($sale['client']&&(owner()||can_clients())):?><div><span>Cliente</span><strong><?=e($sale['client'])?></strong></div><?php endif;?></div><table class="receipt-table"><thead><tr><th>Producto</th><th>Cant.</th><th>P. unit.</th><th>Subtotal</th></tr></thead><tbody><?php foreach($lines as $l):?><tr><td><?=e($l['product_name'])?></td><td><?=e($l['quantity'])?></td><td><?=money($l['unit_price'])?></td><td><?=money($l['line_total'])?></td></tr><?php endforeach;?></tbody></table><div class="receipt-totals"><div>Subtotal <strong><?=money($sale['subtotal'])?></strong></div><div class="total">TOTAL <strong><?=money($sale['total'])?></strong></div><div>Pago en efectivo <strong><?=money($sale['cash_received'])?></strong></div><div>Cambio <strong><?=money($sale['cash_change'])?></strong></div></div><footer class="receipt-note"><p>Gracias por su compra.</p><strong>Documento de control interno. No constituye factura fiscal autorizada.</strong></footer></article><?php footer_view();
}
