function reports_view():void{
    require_owner();$date=(string)($_GET['date']??date('Y-m-d'));
    if(!nullable_date($date))render_error('Seleccione una fecha válida.');
    $next=(new DateTimeImmutable($date))->modify('+1 day')->format('Y-m-d');
    $sales=rows('SELECT s.id,s.receipt_no,s.created_at,s.subtotal,s.total,s.cash_received,s.cash_change,u.name responsible FROM sales s JOIN users u ON u.id=s.user_id WHERE s.created_at>=? AND s.created_at<? ORDER BY s.id DESC',[$date,$next]);
    $total=0;foreach($sales as $s)$total+=cents((string)$s['total']);
    header_view('Reporte de ventas','Consulte los resultados del día seleccionado y expórtelos a CSV.','reports');
    ?><section class="panel"><form class="report-filter" method="get" action="index.php"><input type="hidden" name="route" value="reports"><label>Fecha del reporte<input type="date" name="date" required value="<?=e($date)?>"></label><button class="btn primary" type="submit">Consultar</button><a class="btn" href="index.php?route=export-sales&date=<?=e($date)?>">Exportar CSV</a></form></section><div class="stats-grid three"><div class="stat-card"><span class="stat-label">Fecha consultada</span><strong class="smaller"><?=e(date('d/m/Y',strtotime($date)))?></strong></div><div class="stat-card"><span class="stat-label">Número de ventas</span><strong><?=count($sales)?></strong></div><div class="stat-card"><span class="stat-label">Total vendido</span><strong><?=money(decimal($total))?></strong></div></div><section class="panel"><div class="panel-head"><h2>Operaciones del día</h2></div><div class="table-scroll"><table><thead><tr><th>Comprobante</th><th>Hora</th><th>Responsable</th><th>Subtotal</th><th>Total</th><th>Efectivo recibido</th><th>Cambio</th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td><a class="text-link" href="index.php?route=receipt&id=<?=$s['id']?>"><?=e($s['receipt_no'])?></a></td><td><?=e(date('H:i',strtotime($s['created_at'])))?></td><td><?=e($s['responsible'])?></td><td><?=money($s['subtotal'])?></td><td><strong><?=money($s['total'])?></strong></td><td><?=money($s['cash_received'])?></td><td><?=money($s['cash_change'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$sales)empty_state('No se registraron ventas durante el día consultado.');?></section><?php footer_view();
}
function settings_view():void{
    require_owner();$s=setting();header_view('Configuración','Datos para el comprobante y período de control de vencimientos.','settings');
    ?><section class="panel form-panel"><form method="post" action="index.php?route=save-settings"><?=csrf_field()?><div class="form-grid"><label>Nombre del establecimiento <span class="required">*</span><input name="business_name" maxlength="140" required value="<?=e($s['business_name']??'')?>"></label><label>Teléfono del establecimiento<input name="business_phone" maxlength="40" type="tel" value="<?=e($s['business_phone']??'')?>"></label><label class="wide">Dirección (si corresponde al comprobante)<input name="business_address" maxlength="250" value="<?=e($s['business_address']??'')?>"></label><label>Días para alerta de vencimiento<input name="expiry_alert_days" type="number" min="0" max="3650" step="1" placeholder="Pendiente de definir" value="<?=e($s['expiry_alert_days']??'')?>"><small>Deje vacío hasta acordar el período con la propietaria.</small></label><label class="wide">Política de conservación (informativa)<input name="retention_policy" maxlength="250" value="<?=e($s['retention_policy']??'')?>"><small>Documente el plazo solo cuando se valide; el sistema no realiza borrados automáticos de operaciones.</small></label></div><div class="form-actions"><button type="submit" class="btn primary">Guardar configuración</button></div></form></section><div class="notice"><strong>Antes de producción:</strong> validar obligaciones sanitarias, fiscales, privacidad, tratamiento de prescripciones, período de conservación, calendario de respaldos, navegadores y horario de operación. Este prototipo no emite facturas fiscales oficiales.</div><?php footer_view();
}
function audit_view():void{
    require_owner();$list=rows('SELECT a.*,u.name responsible FROM audit_log a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 250');
    header_view('Auditoría','Últimos 250 eventos para identificar responsables y cambios.','audit');
    ?><section class="panel"><div class="table-scroll"><table><thead><tr><th>Fecha y hora</th><th>Usuario</th><th>Acción</th><th>Entidad</th><th>Referencia</th><th>Detalle</th></tr></thead><tbody><?php foreach($list as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e($a['responsible']??'Sistema')?></td><td><?=e(str_replace('_',' ',$a['action']))?></td><td><?=e($a['entity_type'])?></td><td><?=e($a['entity_id']??'—')?></td><td><?=e($a['context']?:'—')?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$list)empty_state('No hay eventos auditados.');?></section><?php footer_view();
}
